"use strict";

var _AddEditFilterDialog = require("../AddEditFilterDialog.utils");
describe('changeFilterName', function () {
  it('should generate callback', function () {
    var setFilterName = jest.fn();
    expect((0, _AddEditFilterDialog.changeFilterName)(setFilterName, 'filterName', 'hi123')).toEqual(setFilterName('hi123'));
  });
});
describe('generateHandleSaveCallback', function () {
  it('should generate callback', function () {
    var onSaveFilter = jest.fn();
    var handleDialogClose = jest.fn();
    (0, _AddEditFilterDialog.generateHandleSaveCallback)({
      filterName: 'hi123',
      handleDialogClose: handleDialogClose,
      onSaveFilter: onSaveFilter
    })();
    expect(onSaveFilter.mock.calls[0][0]).toEqual('hi123');
  });
});
describe('generateOpenSaveFilterDialogCallback', function () {
  it('should generate callback', function () {
    var setFilterName = jest.fn();
    var setInputFocus = jest.fn();
    (0, _AddEditFilterDialog.generateOpenSaveFilterDialogCallback)({
      setFilterName: setFilterName,
      setInputFocus: setInputFocus
    })();
    expect(setFilterName.mock.calls[0][0]).toEqual('');
    expect(setInputFocus).toHaveBeenCalled();
  });
});
describe('generateKeyboardPressedCallback', function () {
  it('Enter should call onSaveFilter', function () {
    var onSaveFilter = jest.fn();
    var code = 'Enter';
    (0, _AddEditFilterDialog.generateKeyboardPressedCallback)({
      code: code,
      isOpen: true,
      isSaveDisabled: false,
      onSaveFilter: onSaveFilter
    })();
    expect(onSaveFilter).toHaveBeenCalled();
  });
  it('Enter should NOT call onSaveFilter when dialog is closed', function () {
    var onSaveFilter = jest.fn();
    var code = 'Enter';
    (0, _AddEditFilterDialog.generateKeyboardPressedCallback)({
      code: code,
      isOpen: false,
      isSaveDisabled: false,
      onSaveFilter: onSaveFilter
    })();
    expect(onSaveFilter).toHaveBeenCalledTimes(0);
  });
  it('Another code should NOT call onSaveFilter', function () {
    var onSaveFilter = jest.fn();
    var code = 'SomeCode';
    (0, _AddEditFilterDialog.generateKeyboardPressedCallback)({
      code: code,
      isOpen: true,
      isSaveDisabled: false,
      onSaveFilter: onSaveFilter
    })();
    expect(onSaveFilter).toHaveBeenCalledTimes(0);
  });
  it('Should not save filter when disabled', function () {
    var onSaveFilter = jest.fn();
    var code = 'Enter';
    (0, _AddEditFilterDialog.generateKeyboardPressedCallback)({
      code: code,
      isOpen: true,
      isSaveDisabled: true,
      onSaveFilter: onSaveFilter
    })();
    expect(onSaveFilter).toHaveBeenCalledTimes(0);
  });
});